mapper.insert:
INSERT INTO campus_monitor_run_log (
    run_log_id, monitor_task_id, run_status, trigger_type, start_time,
    scanned_count, match_count, negative_count, alert_count,
    error_message, scheduler_node, create_user_id
) VALUES (
    #{runLogId}, #{monitorTaskId}, #{runStatus}, #{triggerType}, #{startTime},
    #{scannedCount}, #{matchCount}, #{negativeCount}, #{alertCount},
    #{errorMessage}, #{schedulerNode}, #{createUserId}
)

mapper.delete:
DELETE FROM campus_monitor_run_log
WHERE create_time < #{expireBefore}
  AND run_log_id NOT IN (
      SELECT last_run_log_id
      FROM campus_monitor_task
      WHERE last_run_log_id IS NOT NULL
        AND deleted = 0
  )
ORDER BY id ASC
LIMIT #{limit}
